import random

def generate(rng, n):
    brackets = ['()', '{}', '[]']
    s = []
    for _ in range(n // 2):
        b = rng.choice(brackets)
        if rng.random() > 0.5:
            s.append(b)
        else:
            idx = rng.randint(0, len(s))
            s.insert(idx, b)
    res = ''.join([''.join(x) for x in s])
    if len(res) == 0:
        res = "()"
    return [res]

def generate_worst(rng, n):
    # Generates deeply nested open brackets followed by closing ones
    half = n // 2
    res = '(' * half + ')' * half
    return [res]

